-- PT116-S2-Q24. Batch 12.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch12$PT116-S2-Q24$batch12$ AND q.stimulus=$batch12$Politician: The law should not require people to wear seat belts in cars. People are allowed to ride motorcycles without seat belts, and riding a motorcycle even while wearing a seat belt would be more dangerous than riding in a car without wearing one.$batch12$ AND q.prompt=$batch12$Which one of the following arguments is most similar in its flawed reasoning to the politician's argument?$batch12$ AND q.correct_choice=$batch12$C$batch12$) THEN RAISE EXCEPTION 'Question changed: PT116-S2-Q24'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch12$PT116-S2-Q24$batch12$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT116-S2-Q24'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch12$PT116-S2-Q24$batch12$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch12$Conclusion$batch12$, $batch12$The law shouldn't require seat belts in cars.$batch12$), (1, $batch12$Evidence$batch12$, $batch12$People may ride motorcycles without belts, and a motorcycle even with a belt is more dangerous than a car without one.$batch12$), (2, $batch12$Evaluate$batch12$, $batch12$A riskier activity is allowed without a safeguard, so the argument concludes a safer activity shouldn't require one. The two activities may be regulated for different reasons.$batch12$), (3, $batch12$Goal$batch12$, $batch12$A riskier activity is permitted unprotected, so a safer one shouldn't require protection.$batch12$)) v(position,label,body) WHERE q.qid=$batch12$PT116-S2-Q24$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch12$A$batch12$, $batch12$This argues snacks would improve nutrition. No riskier activity permitted.$batch12$), ($batch12$B$batch12$, $batch12$This compares productivity, not risk, and argues for allowing time off.$batch12$), ($batch12$C$batch12$, $batch12$Standing at cliff edges is legal, and even sitting at a cliff edge is riskier than standing on a coaster. So the argument says parks should allow standing. Same move.$batch12$), ($batch12$D$batch12$, $batch12$This argues for a new restriction, the opposite direction.$batch12$), ($batch12$E$batch12$, $batch12$This compares two places that differ only in size. No risk comparison.$batch12$)) v(letter,body) WHERE q.qid=$batch12$PT116-S2-Q24$batch12$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
